WITH cleaned AS (SELECT id, supplier_name, country, city, LENGTH(country) AS country_length, COALESCE(city, 'NONE') AS city_clean FROM suppliers WHERE city IS NOT NULL) SELECT CASE WHEN country_length >= 83 THEN 'HIGH' ELSE 'LOW' END AS country_length_tier, SORT_ARRAY(COLLECT_SET(country)) AS country_list, COUNT(*) AS event_count, ROUND(SUM(country_length) / NULLIF(COUNT(CASE WHEN country = 'JP' THEN 1 END), 0), 2) AS country_length_per_jp, ROUND(SUM(country_length) / NULLIF(COUNT(CASE WHEN city = 'London' THEN 1 END), 0), 2) AS country_length_per_london, PERCENTILE_APPROX(country_length, 0.5) AS country_length_p50 FROM cleaned GROUP BY CASE WHEN country_length >= 83 THEN 'HIGH' ELSE 'LOW' END
